<?php
require __DIR__.'/bootstrap.php';
require_permission('marketing.manage');
$pageTitle='ES MULTISERVICIOS Marketing'; $active='marketing';
$message='';$type='success';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $action=(string)($_POST['action']??'');
 try{
  if($action==='copy'){
   $keys=['hero_kicker','hero_title','hero_text','hero_primary','hero_secondary','solutions_title','solutions_text','izzy_title','izzy_text','cami_title','cami_text','services_title','services_text','affiliate_title','affiliate_text','affiliate_cta','projects_title','why_title','contact_title','contact_text','support_cta'];
   $st=db()->prepare('INSERT INTO landing_content(content_key,lang,content_value) VALUES(?,?,?) ON DUPLICATE KEY UPDATE content_value=VALUES(content_value)');
   foreach(['es','en'] as $lang)foreach($keys as $key)$st->execute([$key,$lang,trim((string)($_POST[$key.'_'.$lang]??''))]);
   log_activity('marketing.copy','Updated bilingual marketing copy'); $message='Bilingual marketing content saved.';
  }elseif($action==='product'){
   $id=(int)($_POST['id']??0);$st=db()->prepare('UPDATE marketing_products SET description_es=?,description_en=?,features_es=?,features_en=?,cta_url=?,sort_order=?,active=? WHERE id=?');
   $st->execute([trim((string)$_POST['description_es']),trim((string)$_POST['description_en']),trim((string)$_POST['features_es']),trim((string)$_POST['features_en']),trim((string)$_POST['cta_url']),(int)$_POST['sort_order'],isset($_POST['active'])?1:0,$id]);$message='Product updated.';
  }elseif($action==='plan_save'){
   $id=(int)($_POST['id']??0);$vals=[trim((string)$_POST['product_key']),trim((string)$_POST['name_es']),trim((string)$_POST['name_en']),trim((string)$_POST['description_es']),trim((string)$_POST['description_en']),trim((string)$_POST['price_label_es']),trim((string)$_POST['price_label_en']),trim((string)$_POST['features_es']),trim((string)$_POST['features_en']),trim((string)$_POST['badge_es']),trim((string)$_POST['badge_en']),trim((string)$_POST['cta_url']),isset($_POST['featured'])?1:0,(int)$_POST['sort_order'],isset($_POST['active'])?1:0];
   if($id){$st=db()->prepare('UPDATE marketing_plans SET product_key=?,name_es=?,name_en=?,description_es=?,description_en=?,price_label_es=?,price_label_en=?,features_es=?,features_en=?,badge_es=?,badge_en=?,cta_url=?,featured=?,sort_order=?,active=? WHERE id=?');$st->execute([...$vals,$id]);}
   else{$st=db()->prepare('INSERT INTO marketing_plans(product_key,name_es,name_en,description_es,description_en,price_label_es,price_label_en,features_es,features_en,badge_es,badge_en,cta_url,featured,sort_order,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute($vals);} $message='Plan saved.';
  }elseif($action==='plan_delete'){
   db()->prepare('DELETE FROM marketing_plans WHERE id=?')->execute([(int)$_POST['id']]);$message='Plan deleted.';
  }elseif($action==='project_save'){
   $id=(int)($_POST['id']??0);$vals=[trim((string)$_POST['title']),trim((string)$_POST['category_es']),trim((string)$_POST['category_en']),trim((string)$_POST['description_es']),trim((string)$_POST['description_en']),trim((string)$_POST['project_url']),(int)$_POST['sort_order'],isset($_POST['active'])?1:0];
   if($id){$st=db()->prepare('UPDATE marketing_projects SET title=?,category_es=?,category_en=?,description_es=?,description_en=?,project_url=?,sort_order=?,active=? WHERE id=?');$st->execute([...$vals,$id]);}else{$st=db()->prepare('INSERT INTO marketing_projects(title,category_es,category_en,description_es,description_en,project_url,sort_order,active) VALUES(?,?,?,?,?,?,?,?)');$st->execute($vals);} $message='Project saved.';
  }
 }catch(Throwable $e){$message=$e->getMessage();$type='error';}
}
$copy=['es'=>landing_content('es'),'en'=>landing_content('en')];
$products=db()->query('SELECT * FROM marketing_products ORDER BY sort_order,id')->fetchAll();
$plans=db()->query('SELECT * FROM marketing_plans ORDER BY product_key,sort_order,id')->fetchAll();
$projects=db()->query('SELECT * FROM marketing_projects ORDER BY sort_order,id')->fetchAll();
require __DIR__.'/_header.php';
$keys=['hero_kicker'=>'Hero eyebrow','hero_title'=>'Hero title','hero_text'=>'Hero description','hero_primary'=>'Primary CTA','hero_secondary'=>'WhatsApp CTA','solutions_title'=>'Solutions title','solutions_text'=>'Solutions intro','izzy_title'=>'IZZY title','izzy_text'=>'IZZY intro','cami_title'=>'CAMI title','cami_text'=>'CAMI intro','services_title'=>'Services title','services_text'=>'Services intro','affiliate_title'=>'Affiliate title','affiliate_text'=>'Affiliate description','affiliate_cta'=>'Affiliate CTA','projects_title'=>'Projects title','why_title'=>'Why us title','contact_title'=>'Contact title','contact_text'=>'Contact description','support_cta'=>'Support CTA'];
?>
