idden" name="action" value="plan_delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="button danger" type="submit">Delete</button></form></div><?php endforeach;?></div><?php endif;?></section>
<section class="panel" id="projects"><div class="panel-head"><div><span class="eyebrow">PROJECTS</span><h2>Projects & case studies</h2></div></div><div class="marketing-card-grid"><?php foreach($projects as $p):?><form class="marketing-card" method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="project_save"><input type="hidden" name="id" value="<?=$p['id']?>"><label>Project<input name="title" value="<?=h($p['title'])?>"></label><div class="form-grid"><label>Category ES<input name="category_es" value="<?=h($p['category_es'])?>"></label><label>Category EN<input name="category_en" value="<?=h($p['category_en'])?>"></label></div><label>Description ES<textarea name="description_es" rows="4"><?=h($p['description_es'])?></textarea></label><label>Description EN<textarea name="description_en" rows="4"><?=h($p['description_en'])?></textarea></label><div class="form-grid"><label>Project URL<input name="project_url" value="<?=h($p['project_url'])?>"></label><label>Order<input type="number" name="sort_order" value="<?=$p['sort_order']?>"></label></div><label class="toggle-line"><input type="checkbox" name="active" <?=$p['active']?'checked':''?>> <span>Published</span></label><button class="button" type="submit">Save project</button></form><?php endforeach;?></div></section>
